create extension if not exists pgcrypto;
create table public.profiles(id uuid primary key references auth.users on delete cascade,username text unique,display_name text not null default '',avatar_url text,bio text,country text,style_preferences text[] not null default '{}',goals text[] not null default '{}',onboarding_completed boolean not null default false,suspended boolean not null default false,created_at timestamptz not null default now());
create table public.user_roles(user_id uuid primary key references auth.users on delete cascade,role text not null check(role in ('admin')));
create table public.closet_items(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users on delete cascade,image_url text,category text not null,name text not null,subcategory text default '',brand text default '',primary_color text not null,secondary_colors text[] default '{}',pattern text default 'solid',material text,fit text default 'regular',season text[] default '{}',style_tags text[] default '{}',favorite boolean not null default false,source text default 'manual',ai_confidence numeric default 0 check(ai_confidence between 0 and 1),created_at timestamptz default now(),updated_at timestamptz default now());
create index closet_owner on public.closet_items(user_id,created_at desc);
create table public.inspiration_uploads(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users on delete cascade,image_url text not null,analysis_json jsonb,created_at timestamptz default now());
create table public.recreations(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users on delete cascade,inspiration_id uuid references public.inspiration_uploads on delete set null,match_score int check(match_score between 0 and 100),status text default 'completed',analysis_json jsonb not null,created_at timestamptz default now());
create table public.recreation_items(id uuid primary key default gen_random_uuid(),recreation_id uuid not null references public.recreations on delete cascade,source_item_json jsonb not null,closet_item_id uuid references public.closet_items on delete set null,match_score int,is_missing boolean,position int);
create table public.outfits(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users on delete cascade,title text not null,source_recreation_id uuid references public.recreations on delete set null,style text,occasion text,favorite boolean default false,created_at timestamptz default now());
create table public.outfit_items(outfit_id uuid references public.outfits on delete cascade,closet_item_id uuid references public.closet_items on delete cascade,position int,primary key(outfit_id,closet_item_id));
create table public.collections(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users on delete cascade,name text not null,cover_url text,created_at timestamptz default now());
create table public.collection_outfits(collection_id uuid references public.collections on delete cascade,outfit_id uuid references public.outfits on delete cascade,primary key(collection_id,outfit_id));
create table public.wear_history(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users on delete cascade,outfit_id uuid not null references public.outfits on delete cascade,worn_on date not null default current_date,unique(user_id,outfit_id,worn_on));
create table public.shared_results(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users on delete cascade,recreation_id uuid references public.recreations on delete cascade,public_token text unique not null default encode(gen_random_bytes(24),'hex'),public_data jsonb not null,is_active boolean default true,created_at timestamptz default now(),expires_at timestamptz);
create table public.subscriptions(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users on delete cascade,provider text default 'whop',provider_membership_id text unique not null,provider_plan_id text not null,plan_key text not null,status text not null,current_period_end timestamptz,cancel_at_period_end boolean default false,last_verified_at timestamptz default now(),created_at timestamptz default now());
create table public.entitlements(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users on delete cascade,key text not null,source text not null,status text not null,expires_at timestamptz,updated_at timestamptz default now(),unique(user_id,key,source));
create table public.billing_webhook_events(id uuid primary key default gen_random_uuid(),provider text default 'whop',provider_event_id text not null,event_type text not null,payload_hash text not null,status text not null default 'processed',received_at timestamptz default now(),processed_at timestamptz default now(),unique(provider,provider_event_id));
create table public.checkout_sessions(id text primary key,user_id uuid not null references auth.users on delete cascade,plan_id text not null,attribution jsonb default '{}',created_at timestamptz default now());
create table public.usage_counters(subject text not null,feature text not null,period text not null,count int not null default 0,primary key(subject,feature,period));
create table public.ai_usage(id uuid primary key default gen_random_uuid(),user_id uuid references auth.users on delete set null,feature text not null,provider text,model text,input_units int default 0,output_units int default 0,estimated_cost numeric,created_at timestamptz default now());
create table public.referrals(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users on delete cascade,code text unique default encode(gen_random_bytes(8),'hex'),referred_user_id uuid references auth.users on delete set null,activated_at timestamptz,created_at timestamptz default now());
create table public.analytics_events(id uuid primary key default gen_random_uuid(),user_id uuid references auth.users on delete set null,event text not null,properties jsonb default '{}',created_at timestamptz default now());
create table public.reports(id uuid primary key default gen_random_uuid(),user_id uuid references auth.users on delete set null,share_token text,reason text not null,status text default 'open',created_at timestamptz default now());
create table public.admin_audit_logs(id uuid primary key default gen_random_uuid(),actor_id uuid references auth.users on delete set null,action text not null,target_id text,created_at timestamptz default now());
create table public.notifications(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users on delete cascade,message text not null,read_at timestamptz,created_at timestamptz default now());
create table public.feature_flags(key text primary key,enabled boolean default false);
insert into public.feature_flags(key) values('virtual_try_on'),('shopping_affiliates'),('social_voting');
create table public.app_settings(key text primary key,value jsonb not null);
insert into public.app_settings values('pricing','{"monthly":7.99,"annual":49.99,"currency":"USD"}');
create function public.new_profile() returns trigger language plpgsql security definer set search_path=public as $$begin insert into public.profiles(id,display_name) values(new.id,coalesce(new.raw_user_meta_data->>'full_name',''));insert into public.referrals(user_id) values(new.id);return new;end$$;
create trigger new_user after insert on auth.users for each row execute function public.new_profile();
-- Every exposed table is RLS protected. Privileged tables have no client write policies.
do $$declare t text;begin for t in select tablename from pg_tables where schemaname='public' loop execute format('alter table public.%I enable row level security',t);end loop;end$$;
create policy profile_read on public.profiles for select to authenticated using(id=auth.uid());
create policy profile_update on public.profiles for update to authenticated using(id=auth.uid()) with check(id=auth.uid());
revoke update on public.profiles from authenticated;
grant update(username,display_name,avatar_url,bio,country,style_preferences,goals,onboarding_completed) on public.profiles to authenticated;
-- CRUD is authorized in server routes; browser can read its own rows only.
do $$declare t text;begin foreach t in array array['closet_items','inspiration_uploads','recreations','outfits','collections','wear_history','shared_results','subscriptions','entitlements','notifications','referrals'] loop execute format('create policy owner_read on public.%I for select to authenticated using(user_id=auth.uid())',t);end loop;end$$;
create policy role_read on public.user_roles for select to authenticated using(user_id=auth.uid());
create policy public_settings on public.app_settings for select using(true);
create policy public_flags on public.feature_flags for select using(true);
create policy own_outfit_items on public.outfit_items for select to authenticated using(exists(select 1 from public.outfits o where o.id=outfit_id and o.user_id=auth.uid()));
create policy own_recreation_items on public.recreation_items for select to authenticated using(exists(select 1 from public.recreations r where r.id=recreation_id and r.user_id=auth.uid()));
create policy own_collection_outfits on public.collection_outfits for select to authenticated using(exists(select 1 from public.collections c where c.id=collection_id and c.user_id=auth.uid()));
-- Atomic reservations prevent concurrent quota bypass. Only service role can invoke.
create function public.consume_usage(p_subject text,p_feature text,p_period text,p_limit int) returns boolean language plpgsql security definer set search_path=public as $$declare n int;begin insert into usage_counters(subject,feature,period,count) values(p_subject,p_feature,p_period,1) on conflict(subject,feature,period) do update set count=usage_counters.count+1 where usage_counters.count<p_limit returning count into n;return n is not null;end$$;
create function public.release_usage(p_subject text,p_feature text,p_period text) returns void language sql security definer set search_path=public as $$update usage_counters set count=greatest(0,count-1) where subject=p_subject and feature=p_feature and period=p_period$$;
create function public.add_closet_item(p_user uuid,p_item jsonb,p_limit int) returns uuid language plpgsql security definer set search_path=public as $$declare result uuid;begin perform pg_advisory_xact_lock(hashtextextended(p_user::text,0));if (select count(*) from closet_items where user_id=p_user)>=p_limit then raise exception 'LIMIT';end if;insert into closet_items(user_id,name,category,primary_color,subcategory,fit,pattern,season,style_tags,brand,ai_confidence,image_url) values(p_user,p_item->>'name',p_item->>'category',p_item->>'primary_color',p_item->>'subcategory',p_item->>'fit',p_item->>'pattern',array(select jsonb_array_elements_text(p_item->'season')),array(select jsonb_array_elements_text(p_item->'style_tags')),p_item->>'brand',(p_item->>'ai_confidence')::numeric,p_item->>'image_url') returning id into result;return result;end$$;
create function public.apply_membership(p_event text,p_type text,p_hash text,p_user uuid,p_membership text,p_plan text,p_key text,p_status text,p_active boolean,p_end timestamptz,p_cancel boolean,p_verified timestamptz) returns boolean language plpgsql security definer set search_path=public as $$begin
perform pg_advisory_xact_lock(hashtextextended(p_membership,0));
if exists(select 1 from billing_webhook_events where provider='whop' and provider_event_id=p_event) then return false;end if;
insert into billing_webhook_events(provider_event_id,event_type,payload_hash) values(p_event,p_type,p_hash);
if exists(select 1 from subscriptions where provider_membership_id=p_membership and last_verified_at>p_verified) then return false;end if;
if exists(select 1 from billing_holds where membership_id=p_membership and active) then p_active:=false;p_status:='revoked';end if;
insert into subscriptions(user_id,provider_membership_id,provider_plan_id,plan_key,status,current_period_end,cancel_at_period_end,last_verified_at) values(p_user,p_membership,p_plan,p_key,p_status,p_end,p_cancel,p_verified) on conflict(provider_membership_id) do update set status=excluded.status,current_period_end=excluded.current_period_end,cancel_at_period_end=excluded.cancel_at_period_end,last_verified_at=excluded.last_verified_at;
insert into entitlements(user_id,key,source,status,expires_at) values(p_user,'rewear_plus',p_membership,case when p_active then 'active' else 'inactive' end,p_end) on conflict(user_id,key,source) do update set status=excluded.status,expires_at=excluded.expires_at,updated_at=now();return true;end$$;
revoke all on function public.consume_usage(text,text,text,int),public.release_usage(text,text,text),public.add_closet_item(uuid,jsonb,int),public.apply_membership(text,text,text,uuid,text,text,text,text,boolean,timestamptz,boolean,timestamptz) from public,anon,authenticated;
grant execute on function public.consume_usage(text,text,text,int),public.release_usage(text,text,text),public.add_closet_item(uuid,jsonb,int),public.apply_membership(text,text,text,uuid,text,text,text,text,boolean,timestamptz,boolean,timestamptz) to service_role;
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('closet-private','closet-private',false,8388608,array['image/webp']),('inspiration-private','inspiration-private',false,8388608,array['image/webp']),('avatars','avatars',false,2097152,array['image/webp']),('share-assets','share-assets',false,8388608,array['image/webp']);
-- Uploads are server processed; only owners can read private objects.
create policy owner_storage_read on storage.objects for select to authenticated using(bucket_id in ('closet-private','inspiration-private','avatars') and (storage.foldername(name))[1]=auth.uid()::text);
create table public.billing_holds(id text primary key,membership_id text not null,active boolean not null default true,reason text not null,updated_at timestamptz default now());
alter table public.billing_holds enable row level security;
